mapper.sql:
WHERE owner_id = #{ownerId}

    AND (
        LOWER(name) LIKE #{keywordPattern}
        OR LOWER(COALESCE(target_field, '')) LIKE #{keywordPattern}
        OR LOWER(COALESCE(description, '')) LIKE #{keywordPattern}
    )


    AND rule_type = #{ruleType}


    AND enabled = #{enabled}

mapper.insert:
